contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        // Drive the contract to an uninitialized state explicitly, then test SetMinSum pre-init.
        uint beforeUninit = c.MinSum(); if (__ESBMC_reverted()) return;
        bool revertedUninit;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedUninit = true; } else { revertedUninit = false; }

        // Now mark initialized and call SetMinSum again; it must revert and leave MinSum at _val.
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint beforeInit = c.MinSum(); if (__ESBMC_reverted()) return;
        bool revertedInit;
        c.SetMinSum(_val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedInit = true; } else { revertedInit = false; }

        assert(
            !revertedUninit && c.MinSum() == _val &&
            revertedInit && beforeInit == _val && c.MinSum() == _val
        );
    }
}

