// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _val) internal {
        uint256 beforeUninit;
        try c.MinSum() returns (uint256 __r) { beforeUninit = __r; } catch { return; }
        bool revertedUninit;
        try c.SetMinSum(_val) { revertedUninit = false; } catch { revertedUninit = true; }
        try c.Initialized() {} catch { return; }
        uint256 beforeInit;
        try c.MinSum() returns (uint256 __r) { beforeInit = __r; } catch { return; }
        bool revertedInit;
        try c.SetMinSum(_val) { revertedInit = false; } catch { revertedInit = true; }
        assertTrue(!revertedUninit && c.MinSum() == _val &&
            revertedInit && beforeInit == _val && c.MinSum() == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
